const used = $workflow.staticData.global.usedSlugs ??= [];
const queue = $input.first().json;
const next = queue.find((t) => !used.includes(t.slug));
if (!next) {
  throw new Error('Topic queue exhausted.');
}
used.push(next.slug);
return [{ json: next }];

